int main() {
    int n;
    double suma = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        double venta;
        scanf("%lf", &venta);
        suma += venta;
    }
    printf("%.2f\n", suma / n);
    return 0;
}

