#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    int libros = 0, materiales =  0, otros = 0;
    for (int i = 0; i < n; i++) {
        double venta;
        scanf("%lf", &venta);
        if (venta < 50) {
            libros++;
        } else if (venta < 200) {
            materiales++;
        } else {
            otros++;
        }
    }
    printf("Libros: %d\nMateriales: %d\nOtros: %d\n", libros, materiales, otros);
    return 0;
}
